import { useEffect } from "react";
import { useParams } from "react-router-dom";

// Maker pages live only as static HTML in public/makers/<id>/ (generated by scripts/build-makers.mjs).
// This route just hands off to that single copy if the app ever catches a maker URL.
export default function MakerCollection() {
  const { makerId } = useParams();
  useEffect(() => {
    if (makerId) window.location.replace(`/makers/${encodeURIComponent(makerId)}/index.html${window.location.hash}`);
  }, [makerId]);
  return <p className="p-8">Opening the maker collection…</p>;
}
